/* InSe art adapted from the supplied Opus design template. */
// Dot-matrix / halftone art generator for InSe mockups.
// Usage: <div data-art="slabs" data-fg="#fff" data-step="9" style="width:..;height:.."></div>
(function(){
  const NS='http://www.w3.org/2000/svg';
  const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));

  function field(el,fn,opt){
    const W=el.clientWidth,H=el.clientHeight,s=Math.max(5,Math.min(24,+(el.dataset.step||opt.step||9)));
    const fg=el.dataset.fg||'#0B0B0B', red=el.dataset.red||'#D71921';
    const svg=document.createElementNS(NS,'svg');
    svg.setAttribute('width',W);svg.setAttribute('height',H);svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');svg.dataset.inseArt='true';svg.style.setProperty('--art-fg',fg);
    let out='';
    const ghost=el.dataset.ghost; // faint background grid colour
    for(let y=s/2;y<H;y+=s){for(let x=s/2;x<W;x+=s){
      const r=fn(x/W,y/H,x,y,W,H);
      let v=r, c='var(--art-fg)';
      if(typeof r==='object'&&r){v=r.v;c=r.red?red:'var(--art-fg)'}
      if(v>0.05){out+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(s*0.46*clamp(v)).toFixed(2)}" fill="${c}"/>`}
      else if(ghost){out+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(s*0.08).toFixed(2)}" fill="${ghost}"/>`}
    }}
    svg.innerHTML=out;el.replaceChildren(svg);
  }

  // ---------- stacked iso slabs ----------
  function slabs(u,v,x,y,W,H,el){
    const n=+(el.dataset.n||4), cx=W*.5, a=W*(+(el.dataset.a||.40)), b=a*.5, gap=+(el.dataset.gap||.13)*H, t=H*.035;
    const top0=H*.5-(n-1)*gap/2;
    for(let i=0;i<n;i++){
      const cy=top0+i*gap - (el.dataset.lift&&i===0? H*.05:0);
      const dx=x-cx, dy=y-cy;
      const d=Math.abs(dx)/a+Math.abs(dy)/b;
      if(d<=1){
        // local lattice coords
        const p=(dx/a+dy/b), q=(-dx/a+dy/b);
        const N=+(el.dataset.lat||7);
        const atom=Math.pow(Math.max(0,Math.cos(Math.PI*2*p*N)*Math.cos(Math.PI*2*q*N)),3);
        const grad=.35+.35*(1-(dy/b+1)/2)+.15*(dx/a);
        return {v:clamp(.16+grad*.35+atom*.55)*(i===0?1:.82)};
      }
      // side faces (below lower edges)
      const yl=cy+b*(1-Math.abs(dx)/a);
      if(Math.abs(dx)<=a && y>yl && y<=yl+t){
        const front=dx<0?.92:.7;
        if(i===0 && dx>a*.45 && dx<a*.82 && el.dataset.accent!=='0') return {v:1,red:true};
        return {v:front};
      }
    }
    return 0;
  }

  // ---------- halftone sphere with orbit ----------
  function sphere(u,v,x,y,W,H,el){
    const cx=W/2,cy=H/2,R=Math.min(W,H)*(+(el.dataset.r||.24));
    const dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy);
    // orbits
    const orb=(ang,rx,ry)=>{const c=Math.cos(ang),s=Math.sin(ang);const X=(dx*c+dy*s)/rx,Y=(-dx*s+dy*c)/ry;return Math.abs(Math.hypot(X,Y)-1)}
    const o1=orb(-.45,R*1.9,R*.62), o2=orb(.9,R*1.75,R*.5);
    const rx=cx+R*1.55, ry=cy-R*.95;
    if(Math.hypot(x-rx,y-ry)<R*.13) return {v:1,red:true};
    if(d<R){
      const nz=Math.sqrt(1-(d/R)**2), lx=-.5,ly=-.6,lz=.62;
      const L=clamp((dx/R*lx+dy/R*ly+nz*lz));
      // equatorial flake (InSe layer) inside sphere
      const fl=Math.abs(dx)/(R*.62)+Math.abs(dy-R*.05)/(R*.3);
      if(fl<1) return {v:.95};
      if(fl<1.18) return 0;
      return {v:.12+L*.75};
    }
    if(o1<.025||o2<.025) return {v:.42};
    return 0;
  }

  // ---------- hexagonal flake growth ----------
  function hexflake(u,v,x,y,W,H,el){
    const cx=W/2,cy=H/2,R=Math.min(W,H)*(+(el.dataset.r||.34));
    const hex=(dx,dy,r)=>{dx=Math.abs(dx);dy=Math.abs(dy);return Math.max(dx*0.866+dy*0.5,dy)/r};
    const h=hex(x-cx,y-cy,R);
    if(h<1){
      const rings=.5+.5*Math.cos(h*Math.PI*7);
      return {v:clamp(.95-h*.65+rings*.12)};
    }
    // satellite nuclei
    const sats=[[.18,.22,.07],[.83,.74,.05],[.8,.2,.035],[.2,.8,.04]];
    for(const [sx,sy,sr] of sats){const hh=hex(x-sx*W,y-sy*H,sr*W);if(hh<1)return {v:.85-hh*.4,red:sr===.035}}
    // precursor flow lines
    const flow=.5+.5*Math.sin(u*40+Math.sin(v*6)*2);
    if(flow>.96 && v<.12) return {v:.25};
    return 0;
  }

  // ---------- side-view layered structure (Se-In-In-Se) ----------
  function layers(u,v,x,y,W,H,el){
    const s=+(el.dataset.step||9);
    const row=Math.round((y-s/2)/s), col=Math.round((x-s/2)/s);
    const ql=6; // rows per period: 4 atom rows + 2 gap
    const k=row%ql, layer=Math.floor(row/ql);
    const mx=Math.min(u,1-u)*7; const edge=clamp(mx);
    if(k>=4) return 0;
    const isSe=(k===0||k===3);
    const shift=(layer%3)*1; // ABC stacking offset
    const on=((col+shift+(k===1||k===2?1:0))%2===0);
    if(!on) return isSe?0:0;
    let val=isSe?.95:.5;
    if(layer===2 && k===1 && col===Math.floor(W/s*.62)) return {v:1,red:true};
    return {v:val*edge};
  }

  // ---------- lattice with defects ----------
  function lattice(u,v,x,y,W,H,el){
    const s=+(el.dataset.step||9), g=+(el.dataset.cell||4);
    const col=Math.round((x-s/2)/s), row=Math.round((y-s/2)/s);
    const cols=Math.floor(W/s), rows=Math.floor(H/s);
    const cc=Math.floor(cols/2), rc=Math.floor(rows/2);
    const R=Math.min(cols,rows)*.42;
    const dd=Math.hypot(col-cc,row-rc);
    if(dd>R) return 0;
    const onNode=(col%g===0&&row%g===0);
    const onBond=(col%g===0||row%g===0);
    const vx=cc-cc%g+g, vy=rc-rc%g;
    if(col===vx&&row===vy) return 0; // vacancy
    if(Math.hypot(col-vx,row-vy)<1.5 && !onNode) return 0;
    if(col===vx-g+2&&row===vy+2) return {v:1,red:true}; // interstitial
    if(onNode) return {v:.95};
    if(onBond) return {v:.22};
    return 0;
  }

  // ---------- noise / spectrum strip (for archive & misc) ----------
  function spectrum(u,v,x,y,W,H,el){
    const peaks=[[.18,.55],[.42,.9],[.53,.6],[.71,.75]];
    let h=.05;for(const [p,a] of peaks)h+=a*Math.exp(-((u-p)**2)/.0009);
    h=clamp(h);
    const yy=1-v;
    if(yy<h) return {v:.35+.6*(yy/h), red:Math.abs(u-.42)<.012};
    return 0;
  }

  const MAP={slabs,sphere,hexflake,layers,lattice,spectrum};
  const tracked=new Set(), signatures=new WeakMap(), pending=new Set();
  let frame=0;
  function draw(el,force=false){
    if(!el.isConnected||el.clientWidth<1||el.clientHeight<1)return;
    const fn=MAP[el.dataset.art];if(!fn)return;
    const signature=JSON.stringify([Math.round(el.clientWidth),Math.round(el.clientHeight),el.dataset]);
    if(!force&&signatures.get(el)===signature)return;
    field(el,(u,v,x,y,W,H)=>fn(u,v,x,y,W,H,el),{});
    signatures.set(el,signature);
  }
  function queue(el){
    pending.add(el);if(frame)return;
    frame=requestAnimationFrame(()=>{frame=0;for(const node of pending)draw(node);pending.clear();});
  }
  const sizeObserver=typeof ResizeObserver==='function'?new ResizeObserver(entries=>entries.forEach(entry=>queue(entry.target))):null;
  const visibleObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{
    entries.forEach(entry=>{if(entry.isIntersecting){draw(entry.target);visibleObserver.unobserve(entry.target);}});
  },{rootMargin:'240px'}):null;
  function render(root=document){
    for(const el of tracked){if(!el.isConnected){sizeObserver?.unobserve(el);visibleObserver?.unobserve(el);tracked.delete(el);}}
    const nodes=[];if(root.matches?.('[data-art]'))nodes.push(root);
    nodes.push(...root.querySelectorAll('[data-art]'));
    for(const el of nodes){
      if(!MAP[el.dataset.art])continue;
      if(!tracked.has(el)){tracked.add(el);sizeObserver?.observe(el);visibleObserver?.observe(el);}
      const rect=el.getBoundingClientRect();
      if(!visibleObserver||(rect.bottom>=-240&&rect.top<=innerHeight+240))draw(el);
    }
  }
  window.InSeArt=Object.freeze({render,types:Object.freeze(Object.keys(MAP))});
  window.renderArt=render;
  if(document.readyState!=='loading')render();else document.addEventListener('DOMContentLoaded',()=>render(),{once:true});
  if(!sizeObserver)window.addEventListener('resize',()=>tracked.forEach(queue),{passive:true});
})();

